-- Indexes
CREATE INDEX IX_telco_churn_traintest_dataset ON dbo.telco_churn_traintest (dataset);
CREATE INDEX IX_telco_churn_traintest_tenure ON dbo.telco_churn_traintest (tenure);
CREATE INDEX IX_telco_churn_traintest_internet_service ON dbo.telco_churn_traintest (internet_service);
CREATE INDEX IX_telco_churn_traintest_contract ON dbo.telco_churn_traintest (contract);
CREATE INDEX IX_telco_churn_traintest_payment_method ON dbo.telco_churn_traintest (payment_method);
CREATE INDEX IX_telco_churn_traintest_tenure_group ON dbo.telco_churn_traintest (tenure_group);
GO

-- ============ ANALYTICAL VIEWS ============

-- Churn rate train vs test
CREATE OR ALTER VIEW dbo.v_churn_by_dataset AS
SELECT dataset,
       COUNT(*)                                        AS customers,
       SUM(CAST(churned AS INT))                       AS churned_customers,
       ROUND(100.0 * SUM(CAST(churned AS INT)) / COUNT(*), 1) AS churn_rate_pct,
       ROUND(AVG(monthly_charges), 2)                  AS avg_monthly_charges
FROM dbo.telco_churn_traintest
GROUP BY dataset;;
GO

-- Churn rate by contract
CREATE OR ALTER VIEW dbo.v_churn_by_contract AS
SELECT contract,
       COUNT(*)                                        AS customers,
       SUM(CAST(churned AS INT))                       AS churned_customers,
       ROUND(100.0 * SUM(CAST(churned AS INT)) / COUNT(*), 1) AS churn_rate_pct,
       ROUND(AVG(monthly_charges), 2)                  AS avg_monthly_charges
FROM dbo.telco_churn_traintest
GROUP BY contract;;
GO

-- Churn rate by payment method
CREATE OR ALTER VIEW dbo.v_churn_by_payment AS
SELECT payment_method,
       COUNT(*)                                        AS customers,
       SUM(CAST(churned AS INT))                       AS churned_customers,
       ROUND(100.0 * SUM(CAST(churned AS INT)) / COUNT(*), 1) AS churn_rate_pct,
       ROUND(AVG(monthly_charges), 2)                  AS avg_monthly_charges
FROM dbo.telco_churn_traintest
GROUP BY payment_method;;
GO

-- Churn rate by tenure group
CREATE OR ALTER VIEW dbo.v_churn_by_tenure_group AS
SELECT tenure_group,
       COUNT(*)                                        AS customers,
       SUM(CAST(churned AS INT))                       AS churned_customers,
       ROUND(100.0 * SUM(CAST(churned AS INT)) / COUNT(*), 1) AS churn_rate_pct,
       ROUND(AVG(monthly_charges), 2)                  AS avg_monthly_charges
FROM dbo.telco_churn_traintest
GROUP BY tenure_group;;
GO

-- Contract x dataset split comparison
CREATE OR ALTER VIEW dbo.v_churn_contract_x_dataset AS
SELECT dataset, contract,
       COUNT(*) AS customers,
       SUM(CAST(churned AS INT)) AS churned_customers,
       ROUND(100.0 * SUM(CAST(churned AS INT)) / COUNT(*), 1) AS churn_rate_pct
FROM dbo.telco_churn_traintest
GROUP BY dataset, contract;;
GO

-- Monthly revenue lost to churn
CREATE OR ALTER VIEW dbo.v_revenue_at_risk AS
SELECT contract,
       SUM(CASE WHEN churned = 1 THEN monthly_charges ELSE 0 END) AS lost_monthly_revenue,
       SUM(monthly_charges)                                      AS total_monthly_revenue,
       ROUND(100.0 * SUM(CASE WHEN churned = 1 THEN monthly_charges ELSE 0 END)
             / SUM(monthly_charges), 1)                          AS revenue_at_risk_pct
FROM dbo.telco_churn_traintest
GROUP BY contract;;
GO